#!/usr/bin/env bash
# CI 专用：从 pub get 解析出的锁定插件构建宿主 FFI 库。
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

# Linux/macOS host tests both need the library; device builds use the plugin.
case "$(uname -s)" in
  Linux) LIB_NAME=libvodozemac_bindings_dart.so ;;
  Darwin) LIB_NAME=libvodozemac_bindings_dart.dylib ;;
  *) echo "[ci_build_vod] unsupported host: $(uname -s)" >&2; exit 1 ;;
esac

if ! command -v cargo >/dev/null 2>&1; then
  if [ -f "$HOME/.cargo/env" ]; then
    . "$HOME/.cargo/env"
  else
    curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --profile minimal
    . "$HOME/.cargo/env"
  fi
fi

# package_config resolves PUB_CACHE overrides and avoids selecting multiple
# cached versions with a wildcard. It must have been generated by pub get.
CRATE=$(python3 - <<'PYTHON'
import json
from pathlib import Path
from urllib.parse import unquote, urljoin, urlparse

config = Path('.dart_tool/package_config.json').resolve()
packages = json.loads(config.read_text())['packages']
package = next(p for p in packages if p['name'] == 'flutter_vodozemac')
uri = urlparse(urljoin(config.as_uri(), package['rootUri']))
if uri.scheme != 'file':
    raise SystemExit('flutter_vodozemac must resolve to a local file URI')
print(Path(unquote(uri.path)) / 'rust')
PYTHON
)
if [ ! -f "$CRATE/Cargo.toml" ]; then
  echo "[ci_build_vod] 未找到 flutter_vodozemac rust 源（pub get 先跑）" >&2
  exit 1
fi

BUILD_DIR="$(pwd)/build/vodozemac-host"
echo "[ci_build_vod] cargo build --release ($CRATE)"
cargo build --release --manifest-path "$CRATE/Cargo.toml" --target-dir "$BUILD_DIR"

DEST=../spikes/e2ee-group/rust/target/release
mkdir -p "$DEST"
cp "$BUILD_DIR/release/$LIB_NAME" "$DEST/"
# Both unit tests and the release harness use this explicit path in later steps.
if [ -n "${GITHUB_ENV:-}" ]; then
  printf 'FRB_DART_LOAD_EXTERNAL_LIBRARY_NATIVE_LIB_DIR=%s/\n' "$(cd "$DEST" && pwd)" >> "$GITHUB_ENV"
fi
echo "[ci_build_vod] 已就位："
ls -la "$DEST"
